#include "NodeRuntimeState.h"
NodeRuntimeState::NodeRuntimeState():nodeId_(INVALID_NODE_ID),connectionState_(NodeConnectionState::UNKNOWN),lastSeenAt_(0),lastStateChangeAt_(0),lastResult_(NodeRuntimeResult::NOT_INITIALIZED),activeOutboundMessageId_(INVALID_NODE_MESSAGE_ID),outboundBusy_(false){}
bool NodeRuntimeState::isValid()const{return nodeId_!=INVALID_NODE_ID&&isValidNodeConnectionState(connectionState_)&&isValidNodeRuntimeResult(lastResult_);}
NodeId NodeRuntimeState::nodeId()const{return nodeId_;} NodeConnectionState NodeRuntimeState::connectionState()const{return connectionState_;} NodeTimestamp NodeRuntimeState::lastSeenAt()const{return lastSeenAt_;} NodeTimestamp NodeRuntimeState::lastStateChangeAt()const{return lastStateChangeAt_;} NodeRuntimeResult NodeRuntimeState::lastResult()const{return lastResult_;} bool NodeRuntimeState::outboundBusy()const{return outboundBusy_;} NodeMessageId NodeRuntimeState::activeOutboundMessageId()const{return activeOutboundMessageId_;}
